import { isPlainObject } from "@thi.ng/checks";
import { mergeObjWith, meldObjWith } from "./merge-with";
export const mergeDeepObj = (dest, ...xs) => mergeObjWith((a, b) => isPlainObject(a) && isPlainObject(b) ? mergeDeepObj(a, b) : b, dest, ...xs);
export const meldDeepObj = (dest, ...xs) => meldObjWith((a, b) => isPlainObject(a) && isPlainObject(b) ? meldDeepObj(a, b) : b, dest, ...xs);
